CREATE TABLE calciatore (
  id_calciatore int NOT NULL AUTO_INCREMENT,
  nome varchar(100) NOT NULL,
  cognome varchar(100) DEFAULT NULL,
  `nazionalità` varchar(50) DEFAULT NULL,
  ruolo varchar(50) DEFAULT NULL,
  squadra_id int DEFAULT NULL,
  PRIMARY KEY (id_calciatore),
  KEY squadra_id (squadra_id),
  CONSTRAINT calciatore_ibfk_1 FOREIGN KEY (squadra_id) REFERENCES squadra (id_squadra)
)

